    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT
        self.nodes = None

    @lru_cache(None)
    def number_of_MIS(self, edge_key: tuple) -> int:
        node_list = self.nodes
        n = len(node_list)
        node_index = {node: i for i, node in enumerate(node_list)}
        adj = [set() for _ in range(n)]
        for u, v in edge_key:
            i = node_index[u]
            j = node_index[v]
            if j not in adj[i]: adj[i].add(j)
            if i not in adj[j]: adj[j].add(i)
        num = 0
        for mask in range(1 << n):
            S = [i for i in range(n) if (mask & (1 << i)) != 0]
            independent = True
            for u in S:
                for v in S:
                    if u < v and v in adj[u]:
                        independent = False
                        break
                if not independent: break
            if not independent: continue
            maximal = True
            for i in range(n):
                if i not in S:
                    if not any(j in adj[i] for j in S):
                        maximal = False
                        break
            if maximal:
                num += 1
        return num

