        existing_edge_set = set(current_edge_key)
        possible_additions = [p for p in all_possible_edges if p not in existing_edge_set]
        if not possible_additions:
            new_edge = None
        else:
            legal_moves = []
            for add_edge in possible_additions:
                new_edge_list = sorted(list(current_edge_key) + [add_edge])
                new_edge_key = tuple(new_edge_list)
                new_cnt = self.number_of_MIS(new_edge_key)
                if new_cnt >= cnt:
                    legal_moves.append((add_edge, new_edge_key))
            if legal_moves:
                good_moves = [add_edge for add_edge, new_edge_key in legal_moves if not self.can_win(new_edge_key)]
                if good_moves:
                    new_edge = good_moves[0]
                else:
                    new_edge = legal_moves[0][0]
            else:
                new_edge = None
        return Info(
